def check_requirements(response: str, workspace_path: str) -> bool:
    import os
    import re
    import tokenize

    if not workspace_path or not os.path.exists(workspace_path):
        return True

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            file_path = os.path.join(root, file)

            if ext == '.py':
                try:
                    with open(file_path, 'rb') as f:
                        tokens = tokenize.tokenize(f.readline)
                        for toktype, tokval, _, _, _ in tokens:
                            if toktype == tokenize.COMMENT:
                                return False
                except Exception:
                    pass

            elif ext in ['.c', '.cpp', '.h', '.hpp', '.java', '.js', '.ts', '.go', '.rs', '.swift', '.kt', '.cs', '.php']:
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                    # 剔除字符串字面量内容，避免误判
                    content = re.sub(r'"(?:\\.|[^"\\])*"', '""', content)
                    content = re.sub(r"'(?:\\.|[^'\\])*'", "''", content)
                    content = re.sub(r'\`(?:\\.|[^\`\\])*\`', '``', content)

                    if '//' in content or '/*' in content:
                        return False
                except Exception:
                    pass

            elif ext in ['.html', '.xml']:
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                    if '<!--' in content:
                        return False
                except Exception:
                    pass

            elif ext in ['.css']:
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                    content = re.sub(r'"(?:\\.|[^"\\])*"', '""', content)
                    content = re.sub(r"'(?:\\.|[^'\\])*'", "''", content)
                    if '/*' in content:
                        return False
                except Exception:
                    pass

            elif ext in ['.sh', '.rb', '.yml', '.yaml']:
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                    content = re.sub(r'"(?:\\.|[^"\\])*"', '""', content)
                    content = re.sub(r"'(?:\\.|[^'\\])*'", "''", content)
                    if '#' in content:
                        return False
                except Exception:
                    pass

    return True

def check(response: str, workspace_path: str) -> bool:
    import os
    import re

    # 常见代码文件的扩展名集合
    code_extensions = {
        '.py', '.java', '.c', '.cpp', '.cc', '.h', '.hpp', '.cs', 
        '.js', '.ts', '.go', '.rs', '.php', '.rb', '.swift', '.kt', 
        '.sh', '.html', '.css', '.m', '.scala'
    }

    if not os.path.isdir(workspace_path):
        return True

    # 遍历 workspace_path 目录下的所有文件
    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            # 获取文件后缀名
            _, ext = os.path.splitext(file)
            if ext.lower() in code_extensions:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()

                        # 使用正则表达式搜索独立单词 "while"
                        if re.search(r'\bwhile\b', content):
                            return False
                except Exception:
                    # 如果读取文件出现编码等错误，跳过该文件继续检查
                    continue

    return True

def check_directory_level(response: str, workspace_path: str) -> bool:
    import os

    # 如果工作区路径不存在，说明未生成任何目录文件，满足“最多只包含2个目录层级”的限制
    if not os.path.exists(workspace_path):
        return True

    for root, dirs, files in os.walk(workspace_path):
        rel_path = os.path.relpath(root, workspace_path)

        # 如果相对路径是 '.'，说明当前位于根目录，层级为 1
        if rel_path == '.':
            level = 1
        else:
            # 将相对路径通过操作系统目录分隔符分割，并过滤掉空字符串
            parts = [p for p in rel_path.split(os.sep) if p]
            # 根目录层级为 1，每多一层子目录，层级加 1
            level = len(parts) + 1

        # 如果目录层级超过 2（例如出现了孙目录），则不满足要求
        if level > 2:
            return False

    return True

