def check(response: str, workspace_path: str) -> bool:
    import os
    import re

    # 定义常见的代码文件扩展名
    code_extensions = {
        '.js', '.jsx', '.ts', '.tsx', '.vue', '.html', '.htm', 
        '.css', '.scss', '.sass', '.less', 
        '.py', '.java', '.c', '.cpp', '.h', '.hpp', '.cs', 
        '.go', '.rs', '.php', '.rb', '.swift', '.kt', '.sh'
    }

    if not os.path.isdir(workspace_path):
        return True

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in code_extensions:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()

                    # 剔除代码中的字符串字面量，防止字符串内部文本误判为注释符号
                    content_no_str = re.sub(r'"(?:\\.|[^"\\])*"', '""', content)
                    content_no_str = re.sub(r"'(?:\\.|[^'\\])*'", "''", content_no_str)
                    content_no_str = re.sub(r'`(?:\\.|[^`\\])*`', '``', content_no_str)

                    # 1. 检查 HTML/XML/Vue 等模板注释
                    if '<!--' in content_no_str:
                        return False

                    # 2. 检查 CSS/JS/TS 等常见的多行块注释
                    if '/*' in content_no_str:
                        return False

                    # 3. 检查单行注释 //（负向后瞻 (?<!:) 避免匹配到诸如 http:// 的场景）
                    if re.search(r'(?<!:)\/\/', content_no_str):
                        return False

                    # 4. 检查 Python/Ruby/Shell 等脚本语言的单行注释 #
                    if ext in {'.py', '.rb', '.sh'}:
                        if '#' in content_no_str:
                            return False

                except Exception:
                    # 忽略读取失败的不可处理文件
                    pass

    # 如果遍历所有代码文件后均没有发现任何注释，满足要求，返回 True
    return True

def verify_no_while_loops(response: str, workspace_path: str) -> bool:
    import os
    import re

    # 涵盖前端项目以及可能涉及到的后端项目的常见代码文件扩展名
    code_extensions = {
        '.js', '.jsx', '.ts', '.tsx', '.vue', '.html', '.css',
        '.py', '.java', '.c', '.cpp', '.cs', '.go', '.sh'
    }

    # 匹配各类代码中的 while 循环：
    # 1. \bwhile\s*\( 匹配 while (condition) 或 while(condition) -> 常见于JS, TS, C, Java等
    # 2. \bwhile\s+[\w!\[\'\"] 匹配 while 后面跟条件变量、取反符号、中括号、字符串等 -> 常见于Python, Bash等
    while_pattern = re.compile(r'\bwhile\s*\(|\bwhile\s+[\w!\[\'\"]')

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in code_extensions:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()

                    # 如果匹配到 while 循环特征，则表示未满足“不得出现while循环”的要求
                    if while_pattern.search(content):
                        return False
                except Exception:
                    # 文件若读取异常则跳过，继续检查其他文件
                    continue

    # 遍历所有代码文件均未发现 while 循环，要求满足
    return True

