import os
import re

def verify(response: str, workspace_path: str) -> bool:
    """
    验证生成的代码项目中是否不包含任何形式的注释。
    """
    # 常见的代码文件扩展名
    code_extensions = {
        '.js', '.jsx', '.ts', '.tsx', '.html', '.htm', '.css', 
        '.vue', '.py', '.java', '.c', '.cpp', '.cs', '.go', 
        '.sh', '.rb', '.php', '.swift'
    }

    # 匹配各类注释的正则表达式
    html_comment_pattern = re.compile(r'<!--')
    multi_comment_pattern = re.compile(r'/\*')
    # 匹配行首或带空格前缀的单行注释，防止误匹配诸如 'http://' 等
    single_comment_pattern = re.compile(r'(?m)^\s*//|\s+//')
    # 匹配行首或带空格前缀的井号注释 (针对 Python, Shell 等)
    hash_comment_pattern = re.compile(r'(?m)^\s*#|\s+#')

    # 遍历项目所有文件
    for root, _, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in code_extensions:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()

                        # 检查 HTML 注释 (如 <!--...-->)
                        if html_comment_pattern.search(content):
                            return False

                        # 检查多行/块级注释 (如 /*...*/ )
                        if multi_comment_pattern.search(content):
                            return False

                        # 根据文件的常见语言类型，检查相关的单行注释
                        if ext not in {'.py', '.sh', '.rb'}:
                            if single_comment_pattern.search(content):
                                return False
                        else:
                            if hash_comment_pattern.search(content):
                                return False

                except Exception:
                    # 忽略以非 UTF-8 编码或出现文件读取异常的情况，避免因意外中断判断
                    continue

    # 如果遍历完毕未检测出任何匹配的注释则视为满足要求
    return True

def check_code_lines_odd(response: str, workspace_path: str) -> bool:
