            line_no_str = re.sub(r'".*?"', '""', line_strip)
            line_no_str = re.sub(r"'.*?'", "''", line_no_str)
            line_no_str = re.sub(r"`.*?`", "``", line_no_str)

            # 检查 Python / Shell / Ruby 风格的 '#' 注释
            if ext in {'.py', '.sh', '.rb'}:
                if line_strip.startswith('#!'):
                    continue
                # 非字符串区域一旦出现 '#' 即判定为注释
