            # 检查 JS / TS / C / Java 风格的 '//' 注释
            if ext in {'.js', '.ts', '.jsx', '.tsx', '.vue', '.java', '.c', '.cpp', '.h', '.php', '.go'}:
                # 非字符串区域一旦出现 '//' 即判定为注释
                if '//' in line_no_str:
                    return False

        return True

    # 遍历指定工作空间内的所有文件
    for root, dirs, files in os.walk(workspace_path):
