def check_requirement(response: str, workspace_path: str) -> bool:
    import os
    import re

    # 用于匹配前端文件中的变量与函数声明（如 let task_name, const MAX_COUNT, function add_task）
    decl_pattern = re.compile(r'\b(?:var|let|const|function)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)')

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            if file.endswith('.js') or file.endswith('.html'):
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                except Exception:
                    continue

                # 如果是 HTML 文件，则仅提取 <script> 标签内的 JS 代码
                if file.endswith('.html'):
                    scripts = re.findall(r'<script[^>]*>(.*?)</script>', content, re.IGNORECASE | re.DOTALL)
                    code_to_check = '\n'.join(scripts)
                else:
                    code_to_check = content

                if not code_to_check.strip():
                    continue

                # 移除多行注释和单行注释，避免注释内带有无关的驼峰命名引起误判
                code_to_check = re.sub(r'/\*.*?\*/', '', code_to_check, flags=re.DOTALL)
                code_to_check = re.sub(r'//.*', '', code_to_check)

                for match in decl_pattern.findall(code_to_check):
                    var_name = match

                    # 校验是否为合法的蛇形命名。
                    # 合法的蛇形命名：全小写（或全大写常量），只允许包含字母、数字和下划线
                    is_lower_snake = re.match(r'^[a-z0-9_]+$', var_name)
                    is_upper_snake = re.match(r'^[A-Z0-9_]+$', var_name)

                    if not is_lower_snake and not is_upper_snake:
                        return False

    return True

