        text = re.sub(r'`(?:\\.|[^`\\])*`', '``', text)
        return text

    # 定义常见代码文件的扩展名集合
    code_extensions = {
        '.js', '.jsx', '.ts', '.tsx', '.vue', '.html', '.htm',
