def check_pascal_case_vars(response: str, workspace_path: str) -> bool:
    import os
    import re

    # 用于匹配 js/ts/jsx/tsx/html/vue 等前端文件中，基本变量与函数的声明
    # 仅匹配关键字后紧跟的普通标识符，以此跳过解构赋值的复杂正则处理
    js_var_pattern = re.compile(r'\b(?:let|var|const)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\b')
    js_func_pattern = re.compile(r'\b(?:function|class)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\b')

    # 用于匹配 Python 中的变量赋值及函数、类的声明
    py_var_pattern = re.compile(r'^[ \t]*([a-zA-Z_][a-zA-Z0-9_]*)[ \t]*=[ \t]*[^=]', re.MULTILINE)
    py_func_pattern = re.compile(r'^[ \t]*(?:def|class)[ \t]+([a-zA-Z_][a-zA-Z0-9_]*)\b', re.MULTILINE)

    def is_pascal_case(name: str) -> bool:
        # 满足大驼峰条件：首字母必须大写，且全部由大小写字母及数字组成，不能包含下划线或其他特殊字符
        return bool(re.match(r'^[A-Z][a-zA-Z0-9]*$', name))

    # 遍历项目目录下的代码文件
    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            file_path = os.path.join(root, file)
            ext = os.path.splitext(file)[1].lower()

            try:
                with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                    content = f.read()
            except Exception:
                continue

            # 校验前端主流代码文件
            if ext in ['.js', '.ts', '.jsx', '.tsx', '.html', '.vue']:
                vars_found = js_var_pattern.findall(content)
                funcs_found = js_func_pattern.findall(content)
                for var_name in vars_found + funcs_found:
                    if not is_pascal_case(var_name):
                        return False

            # 校验 Python 文件
            elif ext == '.py':
                vars_found = py_var_pattern.findall(content)
                funcs_found = py_func_pattern.findall(content)
                for var_name in vars_found + funcs_found:
                    if not is_pascal_case(var_name):
                        return False

    return True

