        content = content.replace("http://", "").replace("https://", "")
        # 此正则表达式通过优先级匹配：字符串字面量会被整体匹配从而保护内部可能含有的 // 或 /*
        pattern = re.compile(
            r'//.*?$|/\*[\s\S]*?\*/|\'(?:\\.|[^\\\'])*\'|"(?:\\.|[^\\"])*"|`(?:\\.|[^\\`])*`',
            re.MULTILINE
        )
        for match in pattern.finditer(content):
            s = match.group(0)
            if s.startswith('//') or s.startswith('/*'):
                return True # 发现注释
        return False

    def check_no_comments_in_html(content: str) -> bool:
        # 检查 script 标签内是否有 JS 注释
        scripts = re.findall(r'<script.*?>([\s\S]*?)</script>', content, re.IGNORECASE)
        # 检查 style 标签内是否有 CSS 注释
        styles = re.findall(r'<style.*?>([\s\S]*?)</style>', content, re.IGNORECASE)

        for script in scripts:
            if check_no_comments_in_js(script):
                return True
        for style in styles:
            if check_no_comments_in_js(style):
                return True

        # 移除 scripts 和 styles 标签及其内容，防止内部的字符串由于包含 <!-- 而被误判为 HTML 注释
        content_no_script_style = re.sub(r'<script.*?>[\s\S]*?</script>', '', content, flags=re.IGNORECASE)
        content_no_script_style = re.sub(r'<style.*?>[\s\S]*?</style>', '', content_no_script_style, flags=re.IGNORECASE)

        # 匹配 HTML 注释
        if re.search(r'<!--[\s\S]*?-->', content_no_script_style):
            return True

        return False

    def check_no_comments_in_py(content: str) -> bool:
