            re.MULTILINE
        )
        for match in pattern.finditer(content):
            s = match.group(0)
            if s.startswith('#'):
                # 排除 shebang (#!/bin/...) 以及 编码声明 (# coding: utf-8)
                if not s.startswith('#!') and not re.match(r'#\s*-*-.*coding', s):
