import os
from pathlib import Path

def check(response: str, workspace_path: str) -> bool:
    try:
        workspace = Path(workspace_path).resolve()

        # 确保给定路径存在且是目录
        if not workspace.exists() or not workspace.is_dir():
            return False

        for path in workspace.rglob('*'):
            rel_path = path.relative_to(workspace)

            # 过滤掉路径中包含隐藏目录的部分（如 .git）
            if any(part.startswith('.') for part in rel_path.parts):
                continue

            # 计算该项目的目录层级
            if path.is_dir():
                # 对于目录，它的层级即是 parts 的长度 + 1
                # len(parts) == 0 时，是根目录（第1层）
                # len(parts) == 1 时，是一级子目录（第2层）
                # len(parts) >= 2 时，是二级及以上子目录（第3层及以上），不符合要求
                if len(rel_path.parts) >= 2:
                    return False
            else:
                # 对于文件，它自身不算作目录，其所在的目录就是它的 parent
                # len(parts[:-1]) == 0 时，在根目录下（第1层目录内）
                # len(parts[:-1]) == 1 时，在一级子目录下（第2层目录内）
                # len(parts[:-1]) >= 2 时，在二级及以上子目录下，不符合要求
                if len(rel_path.parts[:-1]) >= 2:
                    return False

        return True
    except Exception:
        # 如果解析路径或遍历时发生意外错误，判定为不满足
        return False

