import os
import re

def check_requirement(response: str, workspace_path: str) -> bool:
    """
    检查人工智能助手生成的代码项目中，是否没有在任何代码文件里书写注释。
    """
    def remove_strings(text):
        # 移除 Python 风格的多行字符串
        text = re.sub(r'"""[\s\S]*?"""', '""', text)
        text = re.sub(r"'''[\s\S]*?'''", "''", text)
        # 移除双引号和单引号字符串，并兼容其内部的转义符号处理
        text = re.sub(r'"(?:\\.|[^"\\])*"', '""', text)
        text = re.sub(r"'(?:\\.|[^'\\])*'", "''", text)
        # 移除 JS 模板字符串的反引号形式
        text = re.sub(r'`(?:\\.|[^`\\])*`', '``', text)
        return text

    def has_js_comments(text):
        # 判断是否存在多行注释
        if '/*' in text:
            return True
        # 判断是否存在单行注释，并避开URL中的 :// 与被转义的 \/\/ 
        if re.search(r'(?<![:\\])//', text):
            return True
        return False

    def has_py_comments(text):
        # 移除可能的脚本头声明 shebang，例如 #!/usr/bin/env python
        text = re.sub(r'^#!.*', '', text)
        # 在字符串被移空的前提下，任何游离的 # 都可以认为是注释标记
        if '#' in text:
            return True
        return False

    # 按注释符号的差异性划定不同代码类型
    js_exts = {
        '.js', '.jsx', '.ts', '.tsx', '.java', '.c', '.cpp', 
        '.cs', '.go', '.php', '.swift', '.kt', '.rs', '.dart',
        '.css', '.scss', '.less'
    }
    py_exts = {'.py', '.rb', '.sh', '.yml', '.yaml'}
    html_exts = {'.html', '.htm', '.vue'}

    for root, _, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext not in js_exts and ext not in py_exts and ext not in html_exts:
                continue

            file_path = os.path.join(root, file)
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()
            except Exception:
                continue

            # 清洗剔除掉字符串以防误判注释符号
            content = remove_strings(content)

            # 根据扩展名分别实施检测策略
            if ext in js_exts:
                if has_js_comments(content):
                    return False
            elif ext in py_exts:
                if has_py_comments(content):
                    return False
            elif ext in html_exts:
                # 检查 HTML 自有的注释符号
                if '<!--' in content:
                    return False

                # 抽离 HTML/Vue 中自带的 Script 和 Style 块，对它们以 JS/CSS 的规则处理
                scripts = re.findall(r'<script\b[^>]*>(.*?)</script>', content, flags=re.IGNORECASE | re.DOTALL)
                for script in scripts:
                    if has_js_comments(script):
                        return False

                styles = re.findall(r'<style\b[^>]*>(.*?)</style>', content, flags=re.IGNORECASE | re.DOTALL)
                for style in styles:
                    if has_js_comments(style):
                        return False

    return True

