        content = re.sub(r'<!--.*?-->', '', content, flags=re.DOTALL)
        content = re.sub(r'#.*', '', content)

        # 去除字符串字面量，避免字符串内容中包含 "for" 导致误判
        content = re.sub(r'"(?:[^"\\]|\\.)*"', '""', content)
        content = re.sub(r"'(?:[^'\\]|\\.)*'", "''", content)
        content = re.sub(r'`[^`]*`', '``', content)

        # 1. 匹配 C/C++/Java/JS/TS 风格的 for 循环 (如 "for(" 或 "for (")
        if re.search(r'\bfor\s*\(', content):
            return True

        # 2. 匹配 异步 JS 循环 (如 "for await (")
        if re.search(r'\bfor\s+await\s*\(', content):
            return True

        # 3. 匹配 Python 风格的 for 循环 (如 "for item in list:")
        if re.search(r'\bfor\s+[a-zA-Z0-9_,\s]+\s+in\s+', content):
            return True

        # 4. 匹配 Vue 或 Angular 等前端模板里的 for 循环指令 (如 "v-for" 或 "*ngFor")
        if re.search(r'\bv-for\b', content) or re.search(r'\*ngFor\b', content):
            return True

        # 5. 匹配 Jinja2 等后端模板中的 for
        if re.search(r'\{%\s*for\b', content):
            return True

        return False

    # 囊括前端常见的代码相关文件扩展名（结合可能的后端语言）
    valid_extensions = {'.html', '.js', '.ts', '.jsx', '.tsx', '.vue', '.css', '.py', '.java', '.cpp', '.c'}

    if not os.path.exists(workspace_path):
        return False

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in valid_extensions:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                        if has_for_loop(content):
                            # 若发现任何形式的 for 循环，则违背了“禁止使用”的要求
                            return False
                except Exception:
                    # 若由于不可预知编码等原因无法读取，直接略过该文件
                    continue

    # 如果遍历检查完所有代码文件均无 for 循环，则满足要求
    return True

def verify(response: str, workspace_path: str) -> bool:
    import os
    import re
    import ast

    if not os.path.exists(workspace_path):
        return False

    def is_lower_camel_case(name: str) -> bool:
        # 豁免 Python 中的魔法变量（例如 __init__, __name__ 等）
        if name.startswith('__') and name.endswith('__'):
            return True

        # 去除前导常见的标识符修饰（如内部变量使用的 _ 和 $ ）
        clean_name = name.lstrip('_$')

        if not clean_name:
            return True

        # 首字母必须是小写字母（若首字母是大写则为大驼峰，全大写则不为小写）
        if not clean_name[0].islower():
            return False

        # 字符串中间不应包含下划线（杜绝蛇形或者全大写带下划线的情况）
        if '_' in clean_name:
            return False

        return True

    # 简单的正则匹配 js/ts 等文件中常见的前端变量声明
    # 这能够抓取大多数由 let, var, const 声明的单个变量名
    js_pattern = re.compile(r'\b(?:var|let|const)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\b')

    # 用于解析 Python 文件中赋值变量名的 AST Visitor
    class PyVarVisitor(ast.NodeVisitor):
        def __init__(self):
            self.variables = []

        def visit_Name(self, node):
            # 记录处于存储上下文（被赋值）的变量名
            if isinstance(node.ctx, ast.Store):
                self.variables.append(node.id)
            self.generic_visit(node)

        def visit_arg(self, node):
            # 记录函数的参数名
            self.variables.append(node.arg)
            self.generic_visit(node)

    found_any_file = False

    for root, _, files in os.walk(workspace_path):
        for file in files:
            file_path = os.path.join(root, file)
            found_any_file = True

            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()
            except Exception:
                continue

            if file.endswith('.py'):
                try:
                    tree = ast.parse(content)
                    visitor = PyVarVisitor()
                    visitor.visit(tree)
                    for var in visitor.variables:
                        if not is_lower_camel_case(var):
                            return False
                except Exception:
                    pass

            elif file.endswith(('.js', '.ts', '.jsx', '.tsx', '.html', '.vue', '.svelte')):
                matches = js_pattern.findall(content)
                for match in matches:
                    if not is_lower_camel_case(match):
                        return False

    # 若项目目录中没有任何文件，默认认为未生成代码项目
    if not found_any_file:
        return False

    return True

