def check_requirements(response: str, workspace_path: str) -> bool:
    import os
    import re

    if not os.path.exists(workspace_path):
        return True

    def remove_strings(text: str, is_python: bool = False) -> str:
        """
        移除代码中所有的字符串字面量内容，避免字符串内部的字符被误判为注释。
        """
        if is_python:
            # 移除Python特有的多行字符串
            text = re.sub(r'"""[\s\S]*?"""', '""', text)
            text = re.sub(r"'''[\s\S]*?'''", "''", text)

        # 移除双引号和单引号字符串（支持转义字符）
        text = re.sub(r'"(?:\\.|[^"\\])*"', '""', text)
        text = re.sub(r"'(?:\\.|[^'\\])*'", "''", text)

        if not is_python:
            # 移除 JS/TS/Vue 的反引号模板字符串
            text = re.sub(r'`(?:\\.|[^`\\])*`', '``', text)

        return text

    # 定义不同类型注释的匹配模式
    regex_html = re.compile(r'<!--[\s\S]*?-->')
    regex_c_block = re.compile(r'/\*[\s\S]*?\*/')
    regex_c_line = re.compile(r'(?<!:)//.*')

    # 需要检查的代码文件类型
    target_extensions = {
        '.html', '.vue', '.js', '.jsx', '.ts', '.tsx', 
        '.css', '.scss', '.less', '.py', '.sh', '.bash', '.yaml', '.yml'
    }

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext not in target_extensions:
                continue

            filepath = os.path.join(root, file)
            try:
                with open(filepath, 'r', encoding='utf-8') as f:
                    content = f.read()
            except Exception:
                continue # 忽略无法读取的文件

            # 根据扩展名判断文件类型并剥离字符串
            is_script = ext in ['.py', '.sh', '.bash', '.yaml', '.yml']
            is_python = ext == '.py'

            clean_content = remove_strings(content, is_python=is_python)

            if is_script:
                lines = clean_content.split('\n')
                for i, line in enumerate(lines):
                    # 忽略脚本第一行的 shebang
                    if i == 0 and line.startswith('#!'):
                        continue
                    # 如果行内存在 # (不在单词中间)，则视为存在注释
                    if re.search(r'(^|\s)#', line):
                        return False
            else:
                # HTML / Vue 文件
                if ext in ['.html', '.vue']:
                    if regex_html.search(clean_content) or regex_c_block.search(clean_content) or regex_c_line.search(clean_content):
                        return False

                # JS / TS 类型文件
                elif ext in ['.js', '.jsx', '.ts', '.tsx']:
                    if regex_c_block.search(clean_content) or regex_c_line.search(clean_content):
                        return False

                # CSS 类型文件
                elif ext in ['.css', '.scss', '.less']:
                    if regex_c_block.search(clean_content) or regex_c_line.search(clean_content):
                        return False

    return True

