    import os
    import re
    import ast

    # 判断是否为小驼峰命名
    def is_lower_camel_case(name: str) -> bool:
        return bool(re.match(r'^[a-z][a-zA-Z0-9]*$', name))

    def get_js_vars(content: str) -> list:
        var_names = []
        # 匹配 var, let, const 声明的简单变量名
        pattern = r'\b(?:let|const|var)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*(?:=|;|,|:|$|\n)'
        for m in re.finditer(pattern, content):
            var_names.append(m.group(1))

        # 匹配 function 定义的函数名（在JS中也属于变量作用域中的定义）
        func_pattern = r'\bfunction\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\('
        for m in re.finditer(func_pattern, content):
            var_names.append(m.group(1))

        return var_names

    def get_py_vars(content: str) -> list:
        var_names = []
        try:
            tree = ast.parse(content)
            for node in ast.walk(tree):
                if isinstance(node, ast.Assign):
                    for target in node.targets:
                        if isinstance(target, ast.Name):
                            var_names.append(target.id)
                elif isinstance(node, ast.AnnAssign):
                    if isinstance(node.target, ast.Name):
                        var_names.append(node.target.id)
                elif isinstance(node, ast.FunctionDef):
                    var_names.append(node.name)
        except Exception:
            pass
        return var_names

    if not os.path.isdir(workspace_path):
        return False

    for root, _, files in os.walk(workspace_path):
        for file in files:
            filepath = os.path.join(root, file)
            ext = os.path.splitext(file)[1].lower()

            try:
                with open(filepath, 'r', encoding='utf-8') as f:
                    content = f.read()
            except Exception:
                continue

            var_names = []
            if ext == '.py':
                var_names = get_py_vars(content)
            elif ext in ['.js', '.jsx', '.ts', '.tsx', '.vue', '.html', '.htm']:
                var_names = get_js_vars(content)

            # 检查提取出的变量名是否均为小驼峰命名
            for name in var_names:
                if not is_lower_camel_case(name):
                    return False

    return True

