def check_no_comments(response: str, workspace_path: str) -> bool:
    import os
    import re

    # 前端项目中常见的代码文件扩展名
    code_extensions = {'.js', '.jsx', '.ts', '.tsx', '.vue', '.html', '.htm', '.css'}

    # 构造正则表达式，按照优先级进行匹配：
    # 1. string: 匹配双引号、单引号及反引号字符串（支持跳过内部转义符，防止内部的斜杠被当做注释）
    # 2. url: 匹配常见的 URL scheme，如 http://, https://，避免将网址中的 // 误判为单行注释
    # 3. comment: 匹配多行注释 (/*...*/)、单行注释 (//...) 以及 HTML注释 (<!--...-->)
    pattern = re.compile(
        r'(?P<string>"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'|`(?:\\.|[^`\\])*`)'
        r'|(?P<url>[a-zA-Z]+://)'
        r'|(?P<comment>/\*[\s\S]*?\*/|//.*|<!--[\s\S]*?-->)'
    )

    for root, _, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in code_extensions:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()

                    # 在文件内容中查找所有匹配项
                    for match in pattern.finditer(content):
                        # 如果匹配命中的分组是 'comment'，说明代码中存在注释
                        if match.lastgroup == 'comment':
                            return False
                except Exception:
                    # 如果因不可预见的情况（如非文本编码）无法读取文件则跳过
                    continue

    # 如果遍历所有代码文件都没有发现任何注释，则满足要求
    return True

