                    return False
                except Exception:
                    # 处理诸如权限不足、文件损坏等其他无法预料的异常
                    return False

    # 如果项目中没有任何代码文件，通常视为生成失败
    if not has_code_file:
        return False

    return True

def check_requirement(response: str, workspace_path: str) -> bool:
    import os
    import re

    camel_case_count = 0
    snake_case_count = 0
    pascal_case_count = 0

    # 匹配多单词命名的正则模式
    camel_pattern = re.compile(r'^[a-z][a-z0-9]*[A-Z][a-zA-Z0-9]*$')
    snake_pattern = re.compile(r'^[a-z0-9]+_[a-z0-9_]*[a-z0-9]+$')
    pascal_pattern = re.compile(r'^[A-Z][a-zA-Z0-9]*$')

    def add_match(name):
        nonlocal camel_case_count, snake_case_count, pascal_case_count
        if camel_pattern.match(name):
            camel_case_count += 1
        elif snake_pattern.match(name):
            snake_case_count += 1
        elif pascal_pattern.match(name):
            pascal_case_count += 1

    if not os.path.exists(workspace_path):
        return False

    for root, dirs, files in os.walk(workspace_path):
        for file in files:
            file_path = os.path.join(root, file)
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read()

                    if file.endswith(('.js', '.jsx', '.ts', '.tsx', '.vue', '.html')):
                        # 1. 匹配 let/const/var 声明的单个变量
                        single_vars = re.findall(r'\b(?:let|const|var)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\b', content)
                        for v in single_vars:
                            add_match(v)

                        # 2. 匹配 function 定义的函数名
                        funcs = re.findall(r'\bfunction\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\b', content)
                        for f_name in funcs:
                            add_match(f_name)

                        # 3. 匹配使用花括号解构赋值时的变量名称 const { a, b } = obj
                        dict_vars = re.findall(r'\b(?:let|const|var)\s*\{([^}]+)\}', content)
                        for d in dict_vars:
                            names = re.findall(r'[a-zA-Z_$][a-zA-Z0-9_$]*', d)
                            for n in names:
                                add_match(n)

                        # 4. 匹配使用方括号解构赋值时的变量名称 const [ a, b ] = arr
                        array_vars = re.findall(r'\b(?:let|const|var)\s*\[([^\]]+)\]', content)
                        for a in array_vars:
                            names = re.findall(r'[a-zA-Z_$][a-zA-Z0-9_$]*', a)
                            for n in names:
                                add_match(n)

                    elif file.endswith('.py'):
                        # Python 变量赋值 (左侧)
                        py_vars = re.findall(r'^[ \t]*([a-zA-Z_][a-zA-Z0-9_]*)\s*=', content, re.MULTILINE)
                        for v in py_vars:
                            add_match(v)
                        # Python def 函数名
                        py_funcs = re.findall(r'\bdef\s+([a-zA-Z_][a-zA-Z0-9_]*)\s*\(', content)
                        for f_name in py_funcs:
                            add_match(f_name)
            except Exception:
                continue

    total = camel_case_count + snake_case_count + pascal_case_count

    # 如果项目中没有任何复杂多词变量，无法判断直接视作容错通过
    if total == 0:
        return True 

    # 判断条件：
    # 小驼峰的数量应当超越了蛇形的数量（说明摒弃了第4轮的蛇形要求）
    # 且不该被大驼峰完全压制（考虑到存在前端组件为大驼峰，通常小驼峰应该远超过组件数量，这里放宽为 ≥ 0.3倍即可）
    if camel_case_count > snake_case_count and camel_case_count >= pascal_case_count * 0.3:
        return True

    # 对于极小文件的容错补偿
    if total < 5 and camel_case_count > 0:
        return True

    return False

import os

def verify(response: str, workspace_path: str) -> bool:
    # 根据用户指令的任务看板项目推断可能的前端代码文件类型
    code_extensions = {'.html', '.css', '.js', '.jsx', '.ts', '.tsx', '.vue'}

    for root, _, files in os.walk(workspace_path):
        for file in files:
            ext = os.path.splitext(file)[1].lower()
            if ext in code_extensions:
                file_path = os.path.join(root, file)
                try:
                    with open(file_path, 'r', encoding='utf-8') as f:
                        for line in f:
                            # 剔除行末的换行符和回车符，保留行内原始空白符等
                            clean_line = line.rstrip('\r\n')
                            # 要求中明确使用了“字符”表述，因此直接使用 len() 统计字符数
                            if len(clean_line) > 70:
                                return False
                except Exception:
                    # 忽略读取过程中的异常（如非UTF-8编码的特殊文件或无法读取的文件）
                    continue

    return True
